  if (/no time|too busy|takes too long|busy schedule/.test(lower))
    return "time pressure";
  if (/expensive|can't afford|cost|pric|budget/.test(lower))
    return "cost and affordability concerns";
  if (/scam|fake|legit|trust|too good/.test(lower))
    return "trust and credibility doubts";
  if (/afraid|scared|fear|worried|risk|fail/.test(lower))
    return "fear of failure";
  if (/stuck|no results|not working|plateau|waste/.test(lower))
    return "frustration with lack of results";
  if (/motivat|consisten|discipline|give up|quit/.test(lower))
    return "motivation and consistency issues";
