  if (/recogni|status|social|influen/.test(lower))
    return "social recognition";
  if (/health|energy|wellness|vitality/.test(lower))
    return "health and wellness";
  if (/transform|life.?chang|success|achieve|breakthrough/.test(lower))
    return "transformational outcome";
