  reasons.push(`Very low confidence (${(confidence * 100).toFixed(0)}%)`);
  if (totalLayers > 0)
    reasons.push(`Only ${layersPassed}/${totalLayers} layers passed`);
  if (!integrityPassed)
    reasons.push("Major integrity failures");
  if (warningCount > 0)
    reasons.push(`${warningCount} structural warning(s)`);
