import { spawn } from "node:child_process";
var PER_CHAIN_WHITELIST = /^[A-Za-z0-9 :=,\[\]*.\-+()_\/]+$/;
var FORBIDDEN_SHELL_META = /[&|$`\n\r\\<>"'\t]/;
var FILTER_COMPLEX_MAX = 4096;
function validateFilterComplex(s) {
  if (typeof s !== "string")
    return { ok: false, reason: "not a string" };
  if (s.length === 0)
    return { ok: false, reason: "empty" };
  if (s.length > FILTER_COMPLEX_MAX)
    return { ok: false, reason: `length>${FILTER_COMPLEX_MAX}` };
  if (FORBIDDEN_SHELL_META.test(s))
    return { ok: false, reason: "shell metacharacter" };
  const chains = s.split(";");
  for (const chain of chains) {
    if (chain.length === 0)
      return { ok: false, reason: "empty filter chain (stray `;`)" };
    if (!PER_CHAIN_WHITELIST.test(chain))
      return { ok: false, reason: "char outside whitelist" };
    if (!chain.startsWith("[") || !chain.includes("]")) {
      return { ok: false, reason: "chain missing input label `[...]`" };
    }
  }
  return { ok: true };
}
function runBinary(bin, args, opts = {}) {
  const timeoutMs = opts.timeoutMs ?? 6e4;
  return new Promise((resolve4, reject2) => {
    const ac = new AbortController();
    const timer = setTimeout(() => ac.abort(), timeoutMs);
    let timedOut = false;
    ac.signal.addEventListener("abort", () => {
      timedOut = true;
    }, { once: true });
    let child;
    try {
      child = spawn(bin, args, { shell: false, signal: ac.signal, cwd: opts.cwd });
    } catch (err) {
      clearTimeout(timer);
      return reject2(err);
    }
    let stdout = "";
    let stderr = "";
    child.stdout?.on("data", (d) => {
      stdout += d.toString();
    });
    child.stderr?.on("data", (d) => {
      stderr += d.toString();
    });
    child.once("error", (err) => {
      clearTimeout(timer);
      reject2(err);
    });
    child.once("close", (code) => {
      clearTimeout(timer);
      if (timedOut)
        return reject2(new Error(`${bin} timed out after ${timeoutMs}ms`));
      if (code === 0)
        return resolve4({ stdout, stderr });
      reject2(new Error(`${bin} exited ${code}: ${stderr.trim().slice(0, 500)}`));
    });
  });
}
function runFfmpeg(args, opts) {
  return runBinary("ffmpeg", args, opts);
}
function runFfprobe(args, opts) {
  return runBinary("ffprobe", args, opts);
}

