async function generateBlueprintForId(blueprintId) {
  const [blueprint] = await db.select().from(strategicBlueprints3).where(eq50(strategicBlueprints3.id, blueprintId)).limit(1);
  if (!blueprint) {
    return { success: false, error: "Blueprint not found" };
  }
  if (!["GATE_PASSED", "EXTRACTION_COMPLETE", "EXTRACTION_FALLBACK", "ANALYSIS_COMPLETE"].includes(blueprint.status)) {
    return { success: false, error: "Blueprint must pass Phase 0 gate before creative blueprint generation" };
  }
  const campaignContext = blueprint.campaignContext ? JSON.parse(blueprint.campaignContext) : null;
  const competitorUrls = blueprint.competitorUrls ? JSON.parse(blueprint.competitorUrls) : [];
  const asp = blueprint.averageSellingPrice;
  const resolvedCampaignId = campaignContext?.campaignId || blueprint.campaignId;
  const [latestMiForCheck] = await db.select().from(miSnapshots10).where(and41(
    eq50(miSnapshots10.accountId, blueprint.accountId),
    eq50(miSnapshots10.campaignId, resolvedCampaignId)
  )).orderBy(desc31(miSnapshots10.createdAt)).limit(1);
  const miReadiness = getEngineReadinessState(
    latestMiForCheck || null,
    resolvedCampaignId,
    ENGINE_VERSION,
    14
  );
  console.log(`[StrategicCore] Phase 1 MI readiness check: state=${miReadiness.state} | campaign=${resolvedCampaignId} | blueprint=${blueprintId}`);
  if (miReadiness.state !== "READY") {
    console.log(`[StrategicCore] Phase 1 blocked \u2014 MI not ready: ${JSON.stringify(miReadiness.diagnostics)}`);
    return {
      success: false,
      error: "MI_NOT_READY"
    };
  }
  let businessData = null;
  if (resolvedCampaignId) {
    const [bd] = await db.select().from(businessDataLayer3).where(eq50(businessDataLayer3.campaignId, resolvedCampaignId)).limit(1);
    if (bd)
      businessData = bd;
  }
  let marketSignals = null;
  if (resolvedCampaignId) {
    const [latestSnapshot] = await db.select({
      marketDiagnosis: miSnapshots10.marketDiagnosis,
      threatSignals: miSnapshots10.threatSignals,
      opportunitySignals: miSnapshots10.opportunitySignals,
      trajectoryData: miSnapshots10.trajectoryData
    }).from(miSnapshots10).where(and41(
      eq50(miSnapshots10.accountId, blueprint.accountId),
      eq50(miSnapshots10.campaignId, resolvedCampaignId),
      inArray15(miSnapshots10.status, ["COMPLETE", "PARTIAL"])
    )).orderBy(desc31(miSnapshots10.createdAt)).limit(1);
    if (latestSnapshot) {
      marketSignals = {
        diagnosis: latestSnapshot.marketDiagnosis,
        threats: latestSnapshot.threatSignals ? JSON.parse(latestSnapshot.threatSignals) : [],
        opportunities: latestSnapshot.opportunitySignals ? JSON.parse(latestSnapshot.opportunitySignals) : [],
        trajectory: latestSnapshot.trajectoryData ? JSON.parse(latestSnapshot.trajectoryData) : null
      };
    }
  }
  let contextBlock = `CAMPAIGN CONTEXT:
`;
  if (campaignContext) {
    contextBlock += `- Campaign: ${campaignContext.campaignName}
`;
    contextBlock += `- Objective: ${campaignContext.objective}
`;
    contextBlock += `- Location: ${campaignContext.location || "Not specified"}
`;
    contextBlock += `- Platform: ${campaignContext.platform || "meta"}
`;
  }
  contextBlock += `- Average Selling Price: $${asp || "Not specified"}
`;
  contextBlock += `- Competitors Tracked: ${competitorUrls.length}
`;
  if (businessData) {
    contextBlock += `
BUSINESS PROFILE:
`;
    contextBlock += `- Business Type: ${businessData.businessType || "Unknown"}
`;
    contextBlock += `- Core Offer: ${businessData.coreOffer || "Unknown"}
`;
    contextBlock += `- Price Range: ${businessData.priceRange || "Unknown"}
`;
    contextBlock += `- Target Audience Age: ${businessData.targetAudienceAge || "Unknown"}
`;
    contextBlock += `- Target Segment: ${businessData.targetAudienceSegment || "Unknown"}
`;
    contextBlock += `- Monthly Budget: ${businessData.monthlyBudget || "Unknown"}
`;
    contextBlock += `- Funnel Objective: ${businessData.funnelObjective || "Unknown"}
`;
    contextBlock += `- Conversion Channel: ${businessData.primaryConversionChannel || "Unknown"}
`;
    if (businessData.businessLocation)
      contextBlock += `- Location: ${businessData.businessLocation}
`;
  }
  if (marketSignals) {
    contextBlock += `
MARKET INTELLIGENCE:
`;
    if (marketSignals.diagnosis) {
      contextBlock += `- Market Diagnosis: ${marketSignals.diagnosis}
`;
    }
    if (marketSignals.threats?.length > 0) {
      contextBlock += `- Threat Signals:
`;
      for (const t of marketSignals.threats.slice(0, 5)) {
        contextBlock += `  \u2022 ${t}
`;
      }
    }
    if (marketSignals.opportunities?.length > 0) {
      contextBlock += `- Market Openings:
`;
      for (const o of marketSignals.opportunities.slice(0, 5)) {
        contextBlock += `  \u2022 ${o}
`;
      }
    }
    if (marketSignals.trajectory) {
      const traj = marketSignals.trajectory;
      contextBlock += `- Market Heating Index: ${traj.marketHeatingIndex ?? "N/A"}
`;
      contextBlock += `- Narrative Convergence: ${traj.narrativeConvergenceScore ?? "N/A"}
`;
    }
  }
  if (competitorUrls.length > 0) {
    contextBlock += `
COMPETITOR URLS:
`;
    for (const url of competitorUrls.slice(0, 10)) {
      contextBlock += `- ${url}
`;
    }
  }
  let engineOutputBlock = "";
  try {
    engineOutputBlock = await loadEngineOutputs(blueprint.accountId, resolvedCampaignId);
    if (engineOutputBlock) {
      contextBlock += `
ENGINE PIPELINE OUTPUTS (use as PRIMARY data source for blueprint fields):
${engineOutputBlock}
`;
      console.log(`[StrategicCore] Engine outputs loaded for blueprint: ${engineOutputBlock.split("\n").filter((l) => l.endsWith(":")).length} engines found`);
    } else {
      console.log(`[StrategicCore] No engine outputs available \u2014 blueprint will use business data and MI only`);
    }
  } catch (err) {
    console.warn(`[StrategicCore] Failed to load engine outputs: ${err.message}`);
  }
  let rawBlueprint = null;
  let extractionFallbackUsed = false;
  let parseFailedReason = null;
  try {
    const response = await aiChat({
      model: "gpt-4.1-mini",
      messages: [
        { role: "system", content: CREATIVE_BLUEPRINT_PROMPT },
        { role: "user", content: `Generate a Creative Blueprint based on this strategic data:

${contextBlock}` }
      ],
      max_tokens: 2e3,
      accountId: blueprint.accountId,
      endpoint: "strategic-creative-blueprint"
    });
    const rawText = typeof response === "string" ? response : response?.choices?.[0]?.message?.content || "";
    const cleaned = cleanJsonString(rawText);
    rawBlueprint = JSON.parse(cleaned);
  } catch (err) {
    console.error("[StrategicCore] Creative blueprint generation attempt 1 failed:", err.message);
    try {
      const retryResponse = await aiChat({
        model: "gpt-4.1-mini",
        messages: [
          { role: "system", content: CREATIVE_BLUEPRINT_PROMPT + "\n\nPREVIOUS ATTEMPT FAILED. Return ONLY a valid JSON object. No markdown. No comments." },
          { role: "user", content: `Generate a Creative Blueprint:

${contextBlock}` }
        ],
        max_tokens: 2e3,
        accountId: blueprint.accountId,
        endpoint: "strategic-creative-blueprint-retry"
      });
      const retryText = typeof retryResponse === "string" ? retryResponse : retryResponse?.choices?.[0]?.message?.content || "";
      const cleaned = cleanJsonString(retryText);
      rawBlueprint = JSON.parse(cleaned);
    } catch (retryErr) {
      console.error("[StrategicCore] Creative blueprint generation attempt 2 failed:", retryErr.message);
    }
  }
  if (!rawBlueprint) {
    extractionFallbackUsed = true;
    parseFailedReason = "AI_GENERATION_FAILED";
    console.warn(`[StrategicCore] Creative blueprint fallback triggered: ${parseFailedReason}`);
    rawBlueprint = {};
  }
  const draftBlueprint = normalizeExtraction(rawBlueprint);
  const allInsufficient = ["detectedOffer", "detectedPositioning", "detectedCTA", "detectedAudienceGuess", "detectedFunnelStage"].every(
    (f) => draftBlueprint[f]?.value === "INSUFFICIENT_DATA"
  );
  if (allInsufficient && !extractionFallbackUsed) {
    extractionFallbackUsed = true;
    parseFailedReason = "EMPTY_FIELDS";
  }
  draftBlueprint.extractionFallbackUsed = extractionFallbackUsed;
  draftBlueprint.parseFailedReason = parseFailedReason;
  draftBlueprint.generationSource = "AI_STRATEGY";
  const finalStatus = extractionFallbackUsed ? "EXTRACTION_FALLBACK" : "EXTRACTION_COMPLETE";
  await db.update(strategicBlueprints3).set({
    status: finalStatus,
    creativeMediaType: "ai_generated",
    draftBlueprint: JSON.stringify(draftBlueprint),
    creativeAnalysis: JSON.stringify(draftBlueprint),
    confirmedBlueprint: null,
    marketMap: null,
    validationResult: null,
    orchestratorPlan: null,
    analysisCompletedAt: /* @__PURE__ */ new Date(),
    updatedAt: /* @__PURE__ */ new Date()
  }).where(eq50(strategicBlueprints3.id, blueprintId));
  await logAuditEvent({
    accountId: blueprint.accountId,
    campaignId: blueprint.campaignId || void 0,
    blueprintId,
    blueprintVersion: blueprint.blueprintVersion,
    event: extractionFallbackUsed ? "CREATIVE_BLUEPRINT_FALLBACK" : "CREATIVE_BLUEPRINT_GENERATED",
    details: {
      source: "AI_STRATEGY",
      allInsufficient,
      extractionFallbackUsed,
      parseFailedReason,
      hasMarketSignals: !!marketSignals,
      hasBusinessData: !!businessData,
      hasEngineOutputs: !!engineOutputBlock
    }
  });
  return {
    success: true,
    blueprintId,
    blueprintVersion: blueprint.blueprintVersion,
    status: finalStatus,
    draftBlueprint,
    extractionFallbackUsed,
    parseFailedReason,
    _meta: {
      source: "AI_STRATEGY",
      allFieldsInsufficient: allInsufficient,
      hasMarketSignals: !!marketSignals,
      hasBusinessData: !!businessData,
      hasEngineOutputs: !!engineOutputBlock,
      engineOutputSections: engineOutputBlock ? engineOutputBlock.split("\n").filter((l) => l.endsWith(":")).map((l) => l.replace(":", "").trim()) : []
    }
  };
}
function registerExtractionRoutes(app2) {
  app2.post("/api/strategic/generate-creative-blueprint", async (req, res) => {
    try {
      const { blueprintId } = req.body;
      if (!blueprintId) {
        return res.status(400).json({ error: "blueprintId is required" });
      }
      const result = await generateBlueprintForId(blueprintId);
      if (!result.success) {
        return res.status(400).json(result);
      }
      res.json(result);
    } catch (error) {
      console.error("[StrategicCore] Creative blueprint generation error:", error.message);
      res.status(500).json({ error: "Failed to generate creative blueprint. Please try again." });
    }
  });
}

