// server/system-control/pre-plan-gate.ts
function decidePrePlanGate(metrics2, thresholds = DEFAULT_UNCERTAINTY_THRESHOLDS) {
  const { aggregatedConfidence: confidence, aggregatedCompleteness: completeness, riskFlags, sampleSize } = metrics2;
  if (sampleSize === 0) {
    return {
      decision: "BLOCK",
      aggregatedConfidence: 0,
      aggregatedCompleteness: 0,
      riskFlags: [],
      reasoning: "No engine outputs to evaluate \u2014 cannot proceed with empty data."
    };
  }
  const criticalFlagCount = riskFlags.length;
  if (criticalFlagCount > thresholds.maxCriticalRiskFlags) {
    return {
      decision: "BLOCK",
      aggregatedConfidence: confidence,
      aggregatedCompleteness: completeness,
      riskFlags,
      reasoning: `Too many risk flags (${criticalFlagCount}/${thresholds.maxCriticalRiskFlags} max). Flags: [${riskFlags.join("; ")}]. Plan generation halted.`
    };
  }
  if (confidence < thresholds.confidenceDowngrade || completeness < thresholds.completenessDowngrade) {
    return {
      decision: "BLOCK",
      aggregatedConfidence: confidence,
      aggregatedCompleteness: completeness,
      riskFlags,
      reasoning: `Confidence (${confidence}%) or completeness (${completeness}%) below minimum threshold (${thresholds.confidenceDowngrade}%). Insufficient data for reliable plan.`
    };
  }
  if (confidence < thresholds.confidenceProceed || completeness < thresholds.completenessProceed) {
    return {
      decision: "DOWNGRADE",
      aggregatedConfidence: confidence,
      aggregatedCompleteness: completeness,
      riskFlags,
      reasoning: `Confidence (${confidence}%) or completeness (${completeness}%) below proceed threshold (${thresholds.confidenceProceed}%). Recommendations marked as low-confidence.`
    };
  }
  return {
    decision: "PROCEED",
    aggregatedConfidence: confidence,
    aggregatedCompleteness: completeness,
    riskFlags,
    reasoning: `All thresholds met. Confidence: ${confidence}%, Completeness: ${completeness}%, Risk flags: ${criticalFlagCount}.`
  };
}

