function repairTruncatedJson(jsonStr) {
  let s = jsonStr.trim();
  if (s.endsWith(","))
    s = s.slice(0, -1);
  let braces = 0;
  let brackets = 0;
  let inString = false;
  let escaped = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (ch === "\\") {
      escaped = true;
      continue;
    }
    if (ch === '"') {
      inString = !inString;
      continue;
    }
    if (inString)
      continue;
    if (ch === "{")
      braces++;
    else if (ch === "}")
      braces--;
    else if (ch === "[")
      brackets++;
    else if (ch === "]")
      brackets--;
  }
  if (inString)
    s += '"';
  const lastChar = s.trim().slice(-1);
  if (lastChar === "," || lastChar === ":")
    s = s.trim().slice(0, -1);
  while (brackets > 0) {
    s += "]";
    brackets--;
  }
  while (braces > 0) {
    s += "}";
    braces--;
  }
  return s;
}
