// server/lib/version-handler.ts
async function resolveBuildSha() {
  let buildSha = process.env.GIT_COMMIT_SHA || "unknown";
  if (buildSha === "unknown") {
    try {
      const fs8 = await import("fs/promises");
      const head = (await fs8.readFile(".git/HEAD", "utf8")).trim();
      if (head.startsWith("ref: ")) {
        const refPath = head.slice(5);
        buildSha = (await fs8.readFile(`.git/${refPath}`, "utf8")).trim().slice(0, 12);
      } else {
        buildSha = head.slice(0, 12);
      }
    } catch {
      buildSha = "unknown";
    }
  }
  return buildSha;
}
async function buildVersionPayload() {
  return {
    version: process.env.npm_package_version || "0.0.0",
    buildSha: await resolveBuildSha(),
    builtAt: process.env.BUILD_TIMESTAMP || null,
    env: process.env.NODE_ENV || "development"
  };
}
async function versionHandler(_req, res) {
  const payload = await buildVersionPayload();
  res.json(payload);
}

