// server/data-source/validation.ts
var ANOMALY_CPA_FLOOR = 1;
var ANOMALY_ROAS_CEILING = 20;
function validateCampaignMetrics(metrics2) {
  const errors = [];
  const warnings = [];
  const anomalies = [];
  if (metrics2.spend <= 0) {
    errors.push("Total Spend must be greater than 0");
  }
  if (metrics2.results <= 0) {
    errors.push("Results (conversions or leads) must be greater than 0");
  }
  if (metrics2.spend > 0 && metrics2.results > 0) {
    const expectedCPA = metrics2.spend / metrics2.results;
    const cpaDeviation = Math.abs(metrics2.cpa - expectedCPA) / Math.max(expectedCPA, 0.01);
    if (cpaDeviation > 0.15) {
      errors.push(`CPA ($${metrics2.cpa.toFixed(2)}) is inconsistent with Spend/Results \u2014 expected ~$${expectedCPA.toFixed(2)}`);
    }
  }
  let computedROAS = null;
  if (metrics2.revenue !== void 0 && metrics2.revenue > 0 && metrics2.spend > 0) {
    computedROAS = metrics2.revenue / metrics2.spend;
  }
  if (metrics2.cpa > 0 && metrics2.cpa < ANOMALY_CPA_FLOOR) {
    anomalies.push(`CPA ($${metrics2.cpa.toFixed(2)}) is below $${ANOMALY_CPA_FLOOR} \u2014 this is unusually low and may indicate data error`);
  }
  if (computedROAS !== null && computedROAS > ANOMALY_ROAS_CEILING) {
    anomalies.push(`ROAS (${computedROAS.toFixed(1)}x) exceeds ${ANOMALY_ROAS_CEILING}x \u2014 this is unusually high and may indicate data error`);
  }
  if (!metrics2.revenue || metrics2.revenue <= 0) {
    warnings.push("Revenue not provided \u2014 ROAS cannot be computed. Financial projections will be limited.");
  }
  if (!metrics2.channelSource) {
    warnings.push("Channel source not specified \u2014 using default platform benchmarks for comparison.");
  }
  return {
    valid: errors.length === 0,
    errors,
    warnings,
    anomalies,
    computedROAS
  };
}
function validateDataSourceMode(mode) {
  return mode === "campaign_metrics" || mode === "benchmark";
}

