function registerExplorationBudgetRoutes(app2) {
  app2.get("/api/exploration-budget/:campaignId", async (req, res) => {
    try {
      const accountId = resolveAccountId(req);
      const campaignId = req.params.campaignId;
      try {
        await assertCampaignBelongsTo(accountId, campaignId);
      } catch (e) {
        if (handleOwnershipError(e, res))
          return;
        throw e;
      }
      const [bizSnap] = await db.select().from(businessDataLayer16).where(and103(eq116(businessDataLayer16.accountId, accountId), eq116(businessDataLayer16.campaignId, campaignId))).orderBy(desc84(businessDataLayer16.createdAt)).limit(1);
      const [campaign2] = await db.select().from(growthCampaigns9).where(eq116(growthCampaigns9.id, campaignId)).limit(1);
      const memBlock = await loadMemoryBlock(campaignId, accountId, bizSnap ? {
        funnelObjective: bizSnap.funnelObjective,
        businessType: bizSnap.businessType,
        monthlyBudget: bizSnap.monthlyBudget
      } : null);
      const [latestPlan] = await db.select().from(strategicPlans24).where(and103(eq116(strategicPlans24.accountId, accountId), eq116(strategicPlans24.campaignId, campaignId))).orderBy(desc84(strategicPlans24.createdAt)).limit(1);
      if (latestPlan?.planJson) {
        try {
          const synthesized = JSON.parse(latestPlan.planJson);
          const explorationBudget2 = await computeExplorationBudget(
            synthesized,
            memBlock.industryBaseline,
            memBlock,
            campaignId,
            accountId,
            campaign2?.explorationBudgetPercent ?? null
          );
          return res.json({ success: true, explorationBudget: explorationBudget2, engine: "v2" });
        } catch (newEngineErr) {
          console.warn(`[ExplorationBudgetRoutes] New engine failed, falling back to legacy:`, newEngineErr.message);
        }
      }
      const budget = parseInt((bizSnap?.monthlyBudget || "1000").replace(/[^0-9]/g, "")) || 1e3;
      const totalWeeklySlots = budget >= 5e3 ? 15 : budget >= 2e3 ? 12 : budget <= 500 ? 7 : 10;
      const explorationBudget = await computeLegacyExplorationBudget(campaignId, accountId, memBlock, totalWeeklySlots);
      res.json({ success: true, explorationBudget, engine: "legacy" });
    } catch (err) {
      console.error(`[ExplorationBudgetRoutes] GET error:`, err.message);
      res.status(500).json({ success: false, error: err.message });
    }
  });
  console.log("[ExplorationBudget] Routes registered: GET /api/exploration-budget/:campaignId");
}

