async function computeRollingBaselines(accountId) {
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1e3);
  const recentData = await db.select({
    avgCpa: sql52`coalesce(avg(${performanceSnapshots10.cpa}), 0)`,
    avgRoas: sql52`coalesce(avg(${performanceSnapshots10.roas}), 0)`,
    avgCtr: sql52`coalesce(avg(${performanceSnapshots10.ctr}), 0)`,
    totalSpend: sql52`coalesce(sum(${performanceSnapshots10.spend}), 0)`
  }).from(performanceSnapshots10).where(and104(eq120(performanceSnapshots10.accountId, accountId), gte15(performanceSnapshots10.fetchedAt, sevenDaysAgo)));
  const currentCpa = Number(recentData[0]?.avgCpa) || 0;
  const currentRoas = Number(recentData[0]?.avgRoas) || 0;
  const currentCtr = Number(recentData[0]?.avgCtr) || 0;
  const currentSpend = Number(recentData[0]?.totalSpend) || 0;
  const previousBaselines = await db.select().from(baselineHistory3).where(eq120(baselineHistory3.accountId, accountId)).orderBy(desc85(baselineHistory3.cycleTimestamp)).limit(3);
  let cpaDriftPercent = 0;
  let roasDriftPercent = 0;
  let ctrDriftPercent = 0;
  let driftSustainedCycles = 0;
  if (previousBaselines.length > 0) {
    const prev = previousBaselines[0];
    const prevCpa = prev.rollingCpa || 0;
    const prevRoas = prev.rollingRoas || 0;
    const prevCtr = prev.rollingCtr || 0;
    if (prevCpa > 0)
      cpaDriftPercent = Math.abs((currentCpa - prevCpa) / prevCpa) * 100;
    if (prevRoas > 0)
      roasDriftPercent = Math.abs((currentRoas - prevRoas) / prevRoas) * 100;
    if (prevCtr > 0)
      ctrDriftPercent = Math.abs((currentCtr - prevCtr) / prevCtr) * 100;
    const anyDrift = cpaDriftPercent > 15 || roasDriftPercent > 15 || ctrDriftPercent > 15;
    if (anyDrift) {
      driftSustainedCycles = (prev.driftSustainedCycles || 0) + 1;
    } else {
      driftSustainedCycles = 0;
    }
  }
  const driftDetected = driftSustainedCycles >= 3;
  await db.insert(baselineHistory3).values({
    accountId,
    rollingCpa: currentCpa,
    rollingRoas: currentRoas,
    rollingCtr: currentCtr,
    rollingSpend: currentSpend,
    driftPercentCpa: cpaDriftPercent,
    driftPercentRoas: roasDriftPercent,
    driftPercentCtr: ctrDriftPercent,
    driftSustainedCycles
  });
  await db.update(accountState11).set({
    driftFlag: driftDetected,
    updatedAt: /* @__PURE__ */ new Date()
  }).where(eq120(accountState11.accountId, accountId));
  if (driftDetected) {
    await logAudit(accountId, "DRIFT_DETECTED", {
      details: {
        cpaDriftPercent,
        roasDriftPercent,
        ctrDriftPercent,
        sustainedCycles: driftSustainedCycles
      }
    });
  } else if (previousBaselines.length > 0 && (previousBaselines[0].driftSustainedCycles || 0) >= 3 && driftSustainedCycles < 3) {
    await logAudit(accountId, "DRIFT_CLEARED", {
      details: { sustainedCycles: driftSustainedCycles }
    });
  }
  return {
    rollingCpa: currentCpa,
    rollingRoas: currentRoas,
    rollingCtr: currentCtr,
    rollingSpend: currentSpend,
    driftDetected,
    driftSustainedCycles,
    driftDetails: {
      cpaDriftPercent,
      roasDriftPercent,
      ctrDriftPercent
    }
  };
}

// server/risk-classifier.ts
function parseBudgetChangePercent(budgetAdjustment) {
  if (!budgetAdjustment)
    return 0;
  const match = budgetAdjustment.match(/[+-]?\d+(\.\d+)?%/);
  if (match) {
    return Math.abs(parseFloat(match[0]));
  }
  const numMatch = budgetAdjustment.match(/[+-]?\d+(\.\d+)?/);
  if (numMatch) {
    return Math.abs(parseFloat(numMatch[0]));
  }
  return 0;
}
function isScalingAction(action) {
  const scalingKeywords = ["scale", "increase budget", "boost", "expand", "double", "triple", "ramp up"];
  const lower = action.toLowerCase();
  return scalingKeywords.some((k) => lower.includes(k));
}
function isPauseAction(action) {
  const pauseKeywords = ["pause", "stop", "halt", "suspend", "disable", "kill"];
  const lower = action.toLowerCase();
  return pauseKeywords.some((k) => lower.includes(k));
}
function isCampaignLaunch(action) {
  const launchKeywords = ["launch campaign", "new campaign", "create campaign", "start campaign"];
  const lower = action.toLowerCase();
  return launchKeywords.some((k) => lower.includes(k));
}
function isCreativeRefresh(action) {
  const refreshKeywords = ["refresh", "regenerate", "new hook", "new creative", "new angle", "new visual"];
  const lower = action.toLowerCase();
  return refreshKeywords.some((k) => lower.includes(k));
}
function classifyDecisionRisk(decision, guardrailResult, acctState) {
  let risk = "low";
  const reasons = [];
  const budgetPercent = parseBudgetChangePercent(decision.budgetAdjustment);
  if (budgetPercent > 30) {
    risk = "high";
    reasons.push(`Budget change ${budgetPercent}% > 30%`);
  } else if (budgetPercent > 15) {
    risk = "medium";
    reasons.push(`Budget change ${budgetPercent}% > 15%`);
  }
  if (isPauseAction(decision.action)) {
    if (risk === "low")
      risk = "high";
    reasons.push("Campaign pause action");
  }
  if (isCampaignLaunch(decision.action)) {
    if (risk === "low")
      risk = "medium";
    reasons.push("New campaign launch");
  }
  if (isScalingAction(decision.action) && budgetPercent > 15) {
    if (risk === "low")
      risk = "medium";
    reasons.push("Scaling action with significant budget increase");
  }
  if (isCreativeRefresh(decision.action) && budgetPercent <= 15) {
    risk = "low";
    reasons.push("Creative refresh with minimal budget impact");
  }
  if (!guardrailResult.overallEligible && risk === "low") {
    risk = "medium";
    reasons.push("Guardrail triggered \u2014 minimum risk elevated to MEDIUM");
  }
  if (acctState.state === "UNSTABLE" || acctState.state === "SAFE_MODE") {
    if (risk === "low") {
      risk = "medium";
      reasons.push(`Account in ${acctState.state} \u2014 risk floor at MEDIUM`);
    }
  }
  if (acctState.volatilityIndex > 0.35) {
    if (risk === "low") {
      risk = "medium";
      reasons.push("High volatility \u2014 risk bumped up");
    } else if (risk === "medium") {
      risk = "high";
      reasons.push("High volatility \u2014 risk bumped from MEDIUM to HIGH");
    }
  }
  if (acctState.driftFlag && isScalingAction(decision.action)) {
    if (risk === "low")
      risk = "medium";
    reasons.push("Baseline drift detected \u2014 scaling restricted");
  }
  let autoExecutable = false;
  if (risk === "low" && guardrailResult.overallEligible && acctState.state === "ACTIVE") {
    autoExecutable = true;
  }
  return {
    riskLevel: risk,
    reason: reasons.length > 0 ? reasons.join("; ") : "Default low-risk classification",
    autoExecutable
  };
}

