function categorizeDecisionType2(action) {
  const lower = action.toLowerCase();
  if (lower.includes("scale") || lower.includes("increase budget") || lower.includes("boost"))
    return "scaling";
  if (lower.includes("pause") || lower.includes("stop") || lower.includes("kill"))
    return "pause";
  if (lower.includes("refresh") || lower.includes("new creative") || lower.includes("new hook"))
    return "creative_refresh";
  if (lower.includes("audience") || lower.includes("targeting"))
    return "audience_optimization";
  if (lower.includes("campaign") || lower.includes("launch"))
    return "campaign_management";
  if (lower.includes("bid") || lower.includes("cpc") || lower.includes("cpm"))
    return "bid_optimization";
  return "general";
}
